<!-- This file is generated by AI. -->

<!--
  自绘窗口标题栏 (取代系统原生标题栏)。

  主窗口在 `tauri.conf.json` 里关掉了原生边框 (`decorations: false`), 由这条栏接管拖拽与窗口
  按钮, 并顺带承载"主题 / 设置"两个入口 —— 开始界面与编辑界面共用同一条栏。

  拖拽与双击最大化交给 Tauri 的 drag region (`data-tauri-drag-region`), 不自己转发鼠标事件:
  自己实现容易在按钮上误触发拖拽, 也拿不到系统级的窗口吸附行为。

  关闭按钮**不直接关窗** —— 它走 `requestClose` (未保存确认), 与系统关闭按钮同一条路径。
-->

<script lang="ts">
  import { getCurrentWindow } from '@tauri-apps/api/window';
  import { onMount } from 'svelte';

  import type { ThemePreference } from '../lib/settings';
  import { appStore, actions } from '../state/store.svelte';
  import { requestClose } from '../unsaved';
  import Icon from './Icon.svelte';
  import type { IconName } from './icons';

  /** 是否已最大化: 决定中间那个按钮是"最大化"还是"还原" */
  let maximized = $state(false);
  const win = getCurrentWindow();
  /** 主题**偏好** (含 `system`); 不是 store 里那个已解析成 light/dark 的 `appStore.theme`。 */
  const preference = $derived(appStore.settings.theme);
  /** 中间那个窗口按钮的图标: 取决于当前是否已最大化。 */
  const maximizeIcon: IconName = $derived(maximized ? 'SquareMultiple' : 'Maximize');

  const THEME_LABELS: Record<ThemePreference, string> = { light: '浅色', dark: '深色', system: '跟随系统' };
  /** 点击顺序: 浅色 → 深色 → 跟随系统 → 浅色。 */
  const THEME_CYCLE: Record<ThemePreference, ThemePreference> = { light: 'dark', dark: 'system', system: 'light' };

  /*
   * 图标分两层: 底图永远是**当前生效的主题** (太阳/月亮), 偏好为"跟随系统"时再压一个显示器
   * 角标。于是四种外观对应三种偏好:
   *   太阳 = 浅色 / 月亮 = 深色 / 太阳+角标 = 跟随系统(系统是浅色) / 月亮+角标 = 跟随系统(系统是深色)
   * 底图取 `appStore.theme` (已解析的生效主题) 而不是偏好: 三态循环里"点一下会变成什么"说不清
   * 自己在哪一档, 而"现在到底是什么颜色"永远有用 —— 系统主题变了, 角标那侧的底图也跟着变。
   */
  const themeIcon: IconName = $derived(appStore.theme === 'dark' ? 'WeatherMoon' : 'WeatherSunny');
  const followingSystem = $derived(preference === 'system');
  const themeTitle = $derived(
    followingSystem
      ? `主题：跟随系统（当前${THEME_LABELS[appStore.theme]}）· 点击切换为${THEME_LABELS[THEME_CYCLE[preference]]}`
      : `主题：${THEME_LABELS[preference]}（点击切换为${THEME_LABELS[THEME_CYCLE[preference]]}）`
  );

  /*
   * 最大化状态只能由窗口事件推出来。
   *
   * 监听 `onResized` 而不是只在挂载时问一次: 用户可以用系统快捷键或把窗口拖到屏幕边缘最大化,
   * 那时按钮图标不改就成了骗人的。
   */
  onMount(() => {
    let disposed = false;
    const sync = () => {
      void win.isMaximized().then((value) => {
        if (!disposed) maximized = value;
      });
    };
    sync();
    const unlisten = win.onResized(sync);
    return () => {
      disposed = true;
      void unlisten.then((off) => off());
    };
  });

  function cycleTheme() {
    actions.updateSettings({ theme: THEME_CYCLE[preference] });
  }
</script>

<header class="title-bar" data-tauri-drag-region>
  <div class="title-bar-brand" data-tauri-drag-region>
    <!-- 应用自己的图标 (与任务栏/安装包同一个), 不用图标字体凑一个 -->
    <img class="title-bar-mark" src="icon.svg" alt="" draggable="false" />
    <span class="title-bar-name">WebGAL Ink</span>
  </div>

  <div class="title-bar-spacer" data-tauri-drag-region></div>

  <div class="title-bar-actions">
    <button
      type="button"
      class="title-bar-action title-bar-theme"
      title={themeTitle}
      aria-label={themeTitle}
      onclick={cycleTheme}
    >
      <Icon name={themeIcon} />
      {#if followingSystem}
        <!-- 角标的内容与尺寸都由 `styles.css` 的 `.title-bar-theme-badge` 决定 -->
        <span class="title-bar-theme-badge"><Icon name="Desktop" /></span>
      {/if}
    </button>
    <button
      type="button"
      class="title-bar-action"
      title="设置"
      onclick={() => {
        actions.setSettingsCategory('editor');
        actions.setSettingsOpen(true);
      }}
    >
      <Icon name="Settings" />
    </button>
  </div>

  <div class="window-controls">
    <button type="button" class="window-control" title="最小化" aria-label="最小化" onclick={() => void win.minimize()}>
      <Icon name="Subtract" />
    </button>
    <button
      type="button"
      class="window-control"
      title={maximized ? '向下还原' : '最大化'}
      aria-label={maximized ? '向下还原' : '最大化'}
      onclick={() => void win.toggleMaximize()}
    >
      <Icon name={maximizeIcon} />
    </button>
    <button
      type="button"
      class="window-control window-control-close"
      title="关闭"
      aria-label="关闭"
      onclick={() => requestClose()}
    >
      <Icon name="Dismiss" />
    </button>
  </div>
</header>
